import{_ as s,o as e,c as n,a5 as p}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"9. 设置最小的项目结构","description":"The Little Book of C 中文版 — 9. 设置最小的项目结构","frontmatter":{"title":"9. 设置最小的项目结构","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","01-入门","中文"],"description":"The Little Book of C 中文版 — 9. 设置最小的项目结构","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":9,"sidebarWeight":9,"alternateZh":"/posts/c教程/zh-CN/01-入门/009-Setting Up a Minimal Project Structure","alternateEn":"/posts/c教程/en-US/01-Getting Started/009-Setting Up a Minimal Project Structure"},"headers":[],"relativePath":"posts/c教程/zh-CN/01-入门/009-Setting Up a Minimal Project Structure.md","filePath":"posts/c教程/zh-CN/01-入门/009-Setting Up a Minimal Project Structure.md","lastUpdated":1790163617000}'),t={name:"posts/c教程/zh-CN/01-入门/009-Setting Up a Minimal Project Structure.md"};function i(c,a,l,o,d,r){return e(),n("div",null,[...a[0]||(a[0]=[p(`<p>[English version](/posts/c教程/en-US/01-Getting Started/009-Setting Up a Minimal Project Structure)</p><p>随着您的 C 程序的增长，您将很快超出单文件“hello.c”样式。真实的项目由多个源文件、标头（有时还包括库）组成。清晰的文件夹结构使您的工作保持干净、易于构建和维护。在本部分中，您将创建一个小型的、有组织的布局，与专业人士使用的结构相同。</p><h4 id="小代码" tabindex="-1">小代码 <a class="header-anchor" href="#小代码" aria-label="Permalink to &quot;小代码&quot;">​</a></h4><p>这是一个最小的项目布局：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my_project/</span></span>
<span class="line"><span>├── include/</span></span>
<span class="line"><span>│   └── greet.h</span></span>
<span class="line"><span>├── src/</span></span>
<span class="line"><span>│   └── greet.c</span></span>
<span class="line"><span>├── main.c</span></span>
<span class="line"><span>└── Makefile</span></span></code></pre></div><p>包含/greet.h</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#ifndef GREET_H</span></span>
<span class="line"><span>#define GREET_H</span></span>
<span class="line"><span>void greet(const char *name);</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><p>src/greet.c</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &quot;greet.h&quot;</span></span>
<span class="line"><span>void greet(const char *name) {</span></span>
<span class="line"><span>    printf(&quot;Hello, %s!\\n&quot;, name);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>主程序</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;greet.h&quot;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    greet(&quot;C Learner&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>生成文件</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CC = gcc</span></span>
<span class="line"><span>CFLAGS = -Wall -Iinclude</span></span>
<span class="line"><span>SRC = main.c src/greet.c</span></span>
<span class="line"><span>OUT = my_program</span></span>
<span class="line"><span>$(OUT): $(SRC)</span></span>
<span class="line"><span>    $(CC) $(CFLAGS) $(SRC) -o $(OUT)</span></span>
<span class="line"><span>clean:</span></span>
<span class="line"><span>    rm -f $(OUT)</span></span></code></pre></div><p>现在构建并运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make</span></span>
<span class="line"><span>./my_program</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hello, C Learner!</span></span></code></pre></div><h4 id="了解结构" tabindex="-1">了解结构 <a class="header-anchor" href="#了解结构" aria-label="Permalink to &quot;了解结构&quot;">​</a></h4><p><code>include/</code>保存头文件（<code>.h</code>)、函数、常量和类型的声明。您将这些包含在<code>.c</code>使用引号的文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;greet.h&quot;</span></span></code></pre></div><p><code>src/</code>包含源文件（<code>.c</code>) 实现标头中声明的函数。</p><p><code>main.c</code>程序的入口点，该文件通常只是调用函数<code>src/</code>.</p><p><code>Makefile</code>定义如何构建程序。你可以运行<code>make</code>而不是输入很长的内容<code>gcc</code>命令。</p><p>输出二进制编译后的可执行文件（这里<code>my_program</code>）为了方便起见保留在项目的根目录中。</p><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>清晰的结构可以帮助您：</p><ul><li>保持代码模块化和可重用</li><li>独立的接口（<code>.h</code>）来自实施（<code>.c</code>)</li><li>使编译更快、更易于管理</li><li>避免大型项目中的名称冲突</li><li>从一个文件扩展到数十个文件而不会造成混乱</li></ul><p>即使小型 C 实用程序也能从结构中受益，当您稍后重新访问代码时，您会感谢自己。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><p>创建如上所示的目录和文件。</p><p>仔细输入每个文件并运行<code>make</code>.</p><p>调整<code>greet.c</code>打印个性化消息，例如</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>printf(&quot;Welcome back, %s!\\n&quot;, name);</span></span></code></pre></div><p>然后重建。</p><p>添加另一对文件，<code>src/farewell.c</code>和<code>include/farewell.h</code>，带有再见函数，并从<code>main.c</code>.</p><p>跑步<code>make clean</code>删除二进制文件并重新构建。</p><p>这个小结构是每​​个严肃的 C 项目的种子。一旦您能够以这种方式组织文件，您就可以成长为其他人可以使用和构建的更大的系统、库、工具和应用程序。</p>`,37)])])}const g=s(t,[["render",i]]);export{u as __pageData,g as default};
